# In-repo support library: all consumers (services/* so's and unit tests)
# only use the static methods of OHOS::NetManagerStandard::NetEventReport.
# The mangled prefix wildcard covers every Send* entry declared in
# net_event_report.h, including dormant ones. HiSysEvent::Domain inline
# constants are COMDAT, each DSO holds its own copy.
{
  global:
    _ZN4OHOS18NetManagerStandard14NetEventReport*;
  local:
    *;
};
